#include <vector>
#include <algorithm>

using namespace std;

class SubsetsTemplate {
public:
    // Generate all subsets with duplicates handled
    vector<vector<int>> subsetsWithDuplicates(vector<int>& nums) {
        sort(nums.begin(), nums.end()); // Mandatory sorting for duplicate matching
        vector<vector<int>> subsets;
        subsets.push_back({}); // Add the initial empty subset

        int start = 0, end = 0;
        for (int i = 0; i < nums.size(); ++i) {
            start = 0;
            // If duplicate, only expand the subsets created in the previous step
            if (i > 0 && nums[i] == nums[i - 1]) {
                start = end + 1;
            }
            end = subsets.size() - 1;

            for (int j = start; j <= end; ++j) {
                vector<int> newSubset = subsets[j];
                newSubset.push_back(nums[i]);
                subsets.push_back(newSubset);
            }
        }
        return subsets;
    }
};

